    topuz: `${uniforma ? "" : `<circle cx="32" cy="12.5" r="4.6" fill="${sac}"/>`}<path d="M20.8 27c-.4-7.9 4.5-12.6 11.2-12.6S43.5 19 43.2 27c-1.9-4.1-5.4-6.3-11.2-6.3S22.7 22.9 20.8 27z" fill="${sac}"/>`,
    yan: `<path d="M20.4 28c-1.3-8.6 4-14.8 11.6-14.8 6.3 0 10.6 3.5 11.8 8.6-3.5-1.9-7-1.6-10.4-3.2-2.6 3.6-7.4 5.1-13 9.4z" fill="${sac}"/>`,
    kirpik: `<path d="M21.2 25.6c1-6.2 5.2-9.8 10.8-9.8s9.8 3.6 10.8 9.8c-3-1.8-6.6-2.7-10.8-2.7s-7.8.9-10.8 2.7z" fill="${sac}"/>`,
    kivircik: `<path d="M20.4 28.6c-.9-8.6 4.6-14.4 11.6-14.4s12.5 5.8 11.6 14.4c-2.2-4.2-6.4-6.6-11.6-6.6s-9.4 2.4-11.6 6.6z" fill="${sac}"/>
      <g fill="${sac}" stroke="rgba(0,0,0,.16)" stroke-width=".6">${kivir(uniforma ? [...AVATAR_KIVIR.slice(0, 2), ...AVATAR_KIVIR.slice(7)] : AVATAR_KIVIR)}</g>`,
