  erzak: { ad: ç("Erzak"), birim: ç("koli"), ikon: "erzak" },
  metal: { ad: ç("İşlenmiş metal"), birim: ç("külçe"), ikon: "metal" },
  kumas: { ad: ç("Kumaş"), birim: ç("top"), ikon: "kumas" },
  muhimmat: { ad: ç("Mühimmat"), birim: ç("adet"), ikon: "muhimmat" },
  techizat: { ad: ç("Teçhizat"), birim: ç("takım"), ikon: "techizat" },
  bakim_kiti: { ad: ç("Bakım kiti"), birim: ç("kutu"), ikon: "bakim" },
  lojistik: { ad: ç("Lojistik paketi"), birim: ç("paket"), ikon: "lojistik" },
