  Object.assign(kontrol, { enableDamping: true, dampingFactor: 0.08, enablePan: false, minDistance: 13, maxDistance: 115,
    minPolarAngle: 0.42, maxPolarAngle: 1.22, autoRotateSpeed: 0.32, enabled: false });
