    g.strokeStyle = "rgba(70,50,10,.55)"; g.lineWidth = 4; g.strokeRect(6, 6, 1012, 84);
    let boy = 46;
    g.font = `700 ${boy}px Georgia, "Times New Roman", serif`;
    while (g.measureText(metin).width > 960 && boy > 20) { boy -= 2; g.font = `700 ${boy}px Georgia, "Times New Roman", serif`; }
    g.fillStyle = "#3B2A0C"; g.textAlign = "center"; g.textBaseline = "middle";
    g.fillText(metin, 512, 51);
